import React from 'react';
import { Link as RouterLink } from 'react-router-dom';
import {
  Alert,
  Box,
  Chip,
  Link,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableRow,
  Typography,
} from '@mui/material';

import {
  labelDataQualityTier,
  labelFactorId,
  labelQuantificationMethod,
  labelScope3Category,
  formatComplianceFlags,
} from '../../shared/carbonCalculationLabels';

export interface TransactionCarbonFootprintDetails {
  co2Emissions?: number;
  quantificationMethod?: string;
  dataQualityTier?: string;
  calculationMethod?: string;
  ghgScope3Category?: string;
  factorLineage?: {
    id?: string;
    factor?: number;
    unit?: string;
    source?: string;
    sourceVersion?: string;
    sourceDocument?: string;
    sourceUrl?: string;
    relativeUncertainty?: number;
    biogenic?: boolean;
  };
  feraSupplement?: { feraKg?: number; ghgScope3Category?: string; upstreamShare?: number };
  complianceFlags?: Record<string, boolean>;
  scope2Reporting?: {
    locationBasedKg?: number;
    marketBasedKg?: number;
    method?: string;
  };
  carbonModelVersion?: string;
  exclusionReason?: string;
  emissionBreakdown?: { scope1?: number; scope2?: number; scope3?: number };
}

interface TransactionCalculationDetailsProps {
  footprint?: TransactionCarbonFootprintDetails | null;
  transactionType?: string;
  category?: string;
  ownership?: string;
  dense?: boolean;
}

const isSalesReviewCandidate = (
  transactionType?: string,
  category?: string,
  exclusionReason?: string
): boolean => {
  const type = String(transactionType || '').toLowerCase();
  const cat = String(category || '').toLowerCase();
  if (type === 'sale' || cat === 'sales' || cat === 'revenue') return true;
  if (exclusionReason === 'revenue_or_sales_non_emitting') return true;
  return false;
};

export const TransactionCalculationDetails: React.FC<TransactionCalculationDetailsProps> = ({
  footprint,
  transactionType,
  category,
  ownership,
  dense = false,
}) => {
  if (!footprint) {
    return (
      <Typography variant="body2" color="text.secondary">
        No calculation details available.
      </Typography>
    );
  }

  const flags = formatComplianceFlags(footprint.complianceFlags || {});
  const feraKg = footprint.feraSupplement?.feraKg;
  const scope3Cat = footprint.ghgScope3Category || footprint.feraSupplement?.ghgScope3Category;
  const salesReview = isSalesReviewCandidate(transactionType, category, footprint.exclusionReason);
  const normalizedCategory = String(category || '').toLowerCase();
  const usesMaintenanceProxy =
    normalizedCategory === 'maintenance'
    || (
      normalizedCategory === 'equipment'
      && ['spend_proxy', 'spend-proxy', 'tier_2_spend'].includes(
        String(footprint.quantificationMethod || footprint.calculationMethod || '').toLowerCase()
      )
    );

  const rows: Array<{ label: string; value: React.ReactNode }> = [
    {
      label: 'Quantification',
      value: labelQuantificationMethod(footprint.quantificationMethod || footprint.calculationMethod),
    },
    {
      label: 'Data quality tier',
      value: (
        <Chip
          size="small"
          label={labelDataQualityTier(footprint.dataQualityTier)}
          color={footprint.dataQualityTier === 'tier_1_activity' ? 'success' : 'default'}
          variant="outlined"
        />
      ),
    },
  ];

  if (scope3Cat) {
    rows.push({ label: 'Scope 3 category', value: labelScope3Category(scope3Cat) });
  }
  if (feraKg && feraKg > 0) {
    rows.push({
      label: 'FERA supplement',
      value: `${Number(feraKg).toFixed(2)} kg CO₂e (Cat 3 — fuel & energy related)`,
    });
  }
  if (footprint.scope2Reporting?.locationBasedKg != null || footprint.scope2Reporting?.marketBasedKg != null) {
    rows.push({
      label: 'Scope 2 dual reporting',
      value: (
        <Stack spacing={0.25}>
          {footprint.scope2Reporting.locationBasedKg != null && (
            <Typography variant="body2">
              Location-based: {Number(footprint.scope2Reporting.locationBasedKg).toFixed(2)} kg CO₂e
            </Typography>
          )}
          {footprint.scope2Reporting.marketBasedKg != null && (
            <Typography variant="body2">
              Market-based: {Number(footprint.scope2Reporting.marketBasedKg).toFixed(2)} kg CO₂e
            </Typography>
          )}
        </Stack>
      ),
    });
  }
  if (footprint.carbonModelVersion) {
    rows.push({ label: 'Model version', value: footprint.carbonModelVersion });
  }
  if (ownership) {
    rows.push({ label: 'Asset ownership', value: ownership.replace(/_/g, ' ') });
  }
  const lineage = footprint.factorLineage;
  if (lineage?.id) {
    rows.push({ label: 'Factor', value: labelFactorId(lineage.id) });
  }
  if (lineage?.factor != null && lineage?.unit) {
    rows.push({
      label: 'Emission factor',
      value: `${lineage.factor} ${lineage.unit}`,
    });
  }
  if (lineage?.source) {
    rows.push({ label: 'Factor source', value: lineage.source });
  }
  if (lineage?.sourceVersion) {
    rows.push({ label: 'Source version', value: lineage.sourceVersion });
  }
  if (lineage?.sourceDocument) {
    rows.push({ label: 'Source document', value: lineage.sourceDocument });
  }
  if (lineage?.sourceUrl) {
    rows.push({
      label: 'Source reference',
      value: (
        <a href={lineage.sourceUrl} target="_blank" rel="noopener noreferrer">
          {lineage.sourceUrl}
        </a>
      ),
    });
  }
  if (lineage?.relativeUncertainty != null) {
    rows.push({
      label: 'Uncertainty',
      value: `±${Math.round(lineage.relativeUncertainty * 100)}%`,
    });
  }
  if (lineage?.biogenic) {
    rows.push({
      label: 'Biogenic',
      value: 'Reported separately — excluded from fossil CO₂e inventory total',
    });
  }
  if (footprint.exclusionReason) {
    rows.push({ label: 'Exclusion reason', value: footprint.exclusionReason.replace(/_/g, ' ') });
  }

  return (
    <Box>
      {usesMaintenanceProxy && (
        <Alert severity="info" sx={{ mb: dense ? 1 : 2 }}>
          Maintenance emissions use a ₹/service-unit proxy. Adjust the unit price under{' '}
          <Link component={RouterLink} to="/msme-profile#carbon-methodology">
            My company → Carbon methodology settings
          </Link>
          .
        </Alert>
      )}
      {salesReview && (
        <Alert severity="warning" sx={{ mb: dense ? 1 : 2 }}>
          This transaction looks like sales or revenue. Compliance inventory excludes non-emitting
          sales flows — review classification if it represents purchased goods or services.
        </Alert>
      )}
      {flags.length > 0 && (
        <Stack direction="row" flexWrap="wrap" gap={0.5} sx={{ mb: dense ? 1 : 2 }}>
          {flags.map((flag: string) => (
            <Chip key={flag} size="small" label={flag} variant="outlined" color="warning" />
          ))}
        </Stack>
      )}
      <Table size="small">
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.label}>
              <TableCell sx={{ width: '40%', fontWeight: 500, border: 0, py: dense ? 0.5 : 1 }}>
                {row.label}
              </TableCell>
              <TableCell sx={{ border: 0, py: dense ? 0.5 : 1 }}>{row.value}</TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </Box>
  );
};

export default TransactionCalculationDetails;
