import React, { useState } from 'react';
import {
  Box,
  Button,
  Collapse,
  Grid,
  Paper,
  Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { Link as RouterLink } from 'react-router-dom';
import { POST_LOGIN_WORKFLOW } from '../../constants/preLoginDashboardContent';
import { PRE_LOGIN_IMAGES } from '../../constants/preLoginDashboardImages';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { POST_LOGIN_WORKFLOW_LOCALE, WORKFLOW_GUIDE_LOCALE } from '../../i18n/glossaryLocale';
import MsmeReadinessLocaleToggle from './MsmeReadinessLocaleToggle';
import PlainLanguageExplainer from './PlainLanguageExplainer';

const WORKFLOW_IMAGES: Record<string, string> = {
  register: PRE_LOGIN_IMAGES.workflowRegister,
  connect: PRE_LOGIN_IMAGES.workflowConnect,
  assess: PRE_LOGIN_IMAGES.workflowAssess,
  report: PRE_LOGIN_IMAGES.workflowReport,
};

const WORKFLOW_LINKS: Record<string, string> = {
  register: '/msme-registration',
  connect: '/document-upload',
  assess: '/carbon-footprint?section=start-assessment',
  report: '/reporting',
};

const STORAGE_KEY = 'msme_workflow_guide_collapsed_v1';

export interface MsmeWorkflowGuidePanelProps {
  /** When true, user can collapse the guide (state persisted). */
  collapsible?: boolean;
}

const MsmeWorkflowGuidePanel: React.FC<MsmeWorkflowGuidePanelProps> = ({ collapsible = true }) => {
  const { locale } = useReadinessLocale();
  const ui = WORKFLOW_GUIDE_LOCALE[locale];

  const [expanded, setExpanded] = useState(() => {
    if (!collapsible || typeof window === 'undefined') {
      return true;
    }
    try {
      return window.localStorage.getItem(STORAGE_KEY) !== '1';
    } catch {
      return true;
    }
  });

  const handleToggle = () => {
    const next = !expanded;
    setExpanded(next);
    if (collapsible && typeof window !== 'undefined') {
      try {
        window.localStorage.setItem(STORAGE_KEY, next ? '0' : '1');
      } catch {
        // ignore
      }
    }
  };

  return (
    <Paper variant="outlined" sx={{ p: 2, mb: 3 }} data-testid="msme-workflow-guide">
      <Box
        sx={{
          display: 'flex',
          alignItems: 'flex-start',
          justifyContent: 'space-between',
          gap: 1,
          mb: expanded ? 1.5 : 0,
          flexWrap: 'wrap',
        }}
      >
        <Box sx={{ flex: 1, minWidth: 220 }}>
          <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
            {ui.title}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {ui.subtitlePrefix}{' '}
            <PlainLanguageExplainer termId="carbon_footprint">carbon footprint</PlainLanguageExplainer>
            {ui.subtitleSuffix}
          </Typography>
        </Box>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
          <MsmeReadinessLocaleToggle compact />
          {collapsible ? (
          <Button
            size="small"
            onClick={handleToggle}
            endIcon={
              <ExpandMoreIcon
                sx={{
                  transform: expanded ? 'rotate(180deg)' : 'rotate(0deg)',
                  transition: 'transform 0.2s',
                }}
              />
            }
            aria-expanded={expanded}
          >
            {expanded ? ui.hide : ui.show}
          </Button>
          ) : null}
        </Box>
      </Box>

      <Collapse in={expanded}>
        <Grid container spacing={2}>
          {POST_LOGIN_WORKFLOW.map((step, index) => {
            const localized = POST_LOGIN_WORKFLOW_LOCALE[locale][index];
            return (
            <Grid item xs={12} sm={6} md={3} key={step.step}>
              <Box
                sx={{
                  height: '100%',
                  border: 1,
                  borderColor: 'divider',
                  borderRadius: 1,
                  p: 1.5,
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 1,
                }}
              >
                <Box
                  component="img"
                  src={WORKFLOW_IMAGES[step.icon]}
                  alt=""
                  aria-hidden
                  sx={{
                    width: '100%',
                    height: 88,
                    objectFit: 'contain',
                    bgcolor: 'action.hover',
                    borderRadius: 1,
                    p: 0.5,
                  }}
                />
                <Typography variant="caption" color="primary.main" sx={{ fontWeight: 700 }}>
                  Step {step.step}
                </Typography>
                <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>
                  {localized?.title ?? step.title}
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ flex: 1 }}>
                  {localized?.description ?? step.description}
                </Typography>
                <Button
                  component={RouterLink}
                  to={WORKFLOW_LINKS[step.icon] || '/'}
                  size="small"
                  variant="text"
                  sx={{ alignSelf: 'flex-start', px: 0 }}
                >
                  {ui.goToStep}
                </Button>
              </Box>
            </Grid>
            );
          })}
        </Grid>
      </Collapse>
    </Paper>
  );
};

export default MsmeWorkflowGuidePanel;
