import React from 'react';
import { FormControl, InputLabel, MenuItem, Select } from '@mui/material';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { READINESS_LOCALE_OPTIONS } from '../../i18n/readinessLocale';

export interface MsmeReadinessLocaleToggleProps {
  /** Compact layout for dashboard headers. */
  compact?: boolean;
}

const MsmeReadinessLocaleToggle: React.FC<MsmeReadinessLocaleToggleProps> = ({ compact = false }) => {
  const { locale, setLocale, strings } = useReadinessLocale();

  return (
    <FormControl size="small" sx={{ minWidth: compact ? 140 : 160 }} data-testid="msme-locale-toggle">
      <InputLabel id="msme-locale-toggle-label">{strings.languageToggleLabel}</InputLabel>
      <Select
        labelId="msme-locale-toggle-label"
        label={strings.languageToggleLabel}
        value={locale}
        onChange={(event) => setLocale(event.target.value as typeof locale)}
      >
        {READINESS_LOCALE_OPTIONS.map((option) => (
          <MenuItem key={option.id} value={option.id}>
            {option.label}
          </MenuItem>
        ))}
      </Select>
    </FormControl>
  );
};

export default MsmeReadinessLocaleToggle;
