import React from 'react';
import { Paper, Typography, Button } from '@mui/material';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import type { OcrValidation } from './OCRValidationBanner';

interface InvoiceUploadWarningProps {
  validation: OcrValidation;
  fileName?: string;
  onReupload?: () => void;
}

const InvoiceUploadWarning: React.FC<InvoiceUploadWarningProps> = ({
  validation,
  fileName,
  onReupload
}) => {
  if (!validation.unreadable && !validation.low_confidence) {
    return null;
  }

  return (
    <Paper variant="outlined" sx={{ p: 2, mb: 2, borderColor: validation.unreadable ? 'error.main' : 'warning.main' }}>
      <Typography variant="subtitle2" gutterBottom>
        {fileName ? `OCR review: ${fileName}` : 'OCR review recommended'}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
        {validation.user_action?.message}
      </Typography>
      {onReupload && (
        <Button size="small" variant="outlined" startIcon={<CloudUploadIcon />} onClick={onReupload}>
          Upload clearer copy
        </Button>
      )}
    </Paper>
  );
};

export default InvoiceUploadWarning;
