import type { OperationalTransaction } from '../components/OperationalTransactionsTable';

const OWNERSHIP_REVIEW_CATEGORIES = new Set(['transportation', 'energy']);

const FUEL_SUBCATEGORIES = new Set([
  'diesel',
  'petrol',
  'cng',
  'lpg',
  'coal',
  'natural_gas',
  'fuel',
]);

export const resolveTransactionOwnership = (
  transaction: Pick<OperationalTransaction, 'ownership' | 'metadata'>
): string => String(transaction.ownership || transaction.metadata?.ownership || '').trim();

export const formatOwnershipLabel = (ownership: string): string => {
  if (!ownership) {
    return 'Needs review';
  }
  return ownership.replace(/_/g, ' ');
};

export const needsOwnershipReview = (
  transaction: Pick<
    OperationalTransaction,
    'category' | 'subcategory' | 'description' | 'ownership' | 'metadata'
  >
): boolean => {
  const category = String(transaction.category || '').toLowerCase();
  if (!OWNERSHIP_REVIEW_CATEGORIES.has(category)) {
    return false;
  }
  if (resolveTransactionOwnership(transaction)) {
    return false;
  }
  if (category === 'transportation') {
    return true;
  }
  const subcategory = String(transaction.subcategory || '').toLowerCase();
  return FUEL_SUBCATEGORIES.has(subcategory);
};

export const countOwnershipReviewCandidates = (
  transactions: Array<
    Pick<OperationalTransaction, 'category' | 'subcategory' | 'description' | 'ownership' | 'metadata'>
  >
): number => transactions.filter(needsOwnershipReview).length;
